INSERT INTO crop_stages (crop_catalog_id,stage_name,sort_order,start_day_estimate,end_day_estimate,expected_observation,recommended_action)
SELECT c.id,s.name,s.ord,s.start_day,s.end_day,s.observation,s.action FROM crop_catalog c CROSS JOIN LATERAL (VALUES
(1,'Levée ou reprise',0,14,'La culture s’installe et de nouvelles pousses apparaissent.','Maintenir une humidité adaptée et vérifier la bonne reprise.'),(2,'Croissance végétative',10,45,'Le feuillage et les tiges se développent activement.','Désherber, surveiller la vigueur et intervenir selon les besoins.'),(3,'Floraison',25,65,'Les fleurs apparaissent ou la culture entre dans sa phase productive.','Maintenir l’irrigation régulière et surveiller l’état général.'),(4,'Formation et grossissement',40,100,'Les organes récoltés se forment ou grossissent progressivement.','Éviter le stress hydrique et poursuivre les observations.'),(5,'Maturation et récolte',70,150,'Les signes de maturité deviennent visibles.','Récolter progressivement au stade souhaité.')
) s(ord,name,start_day,end_day,observation,action) WHERE NOT EXISTS (SELECT 1 FROM crop_stages x WHERE x.crop_catalog_id=c.id);
